    },
}

# 向后兼容：旧主题名映射到新主题名
_LEGACY_MAP = {"dark": "linear", "color": "light", "sharp": "ember"}

# 主题显示名称（用于 UI 按钮）
THEME_LABELS = {
    "linear": "🌑 Linear",
    "light":  "☀ 浅色",
    "rose":   "🌸 玫瑰",
    "ember":  "🔥 琥珀",
}

# 当前激活的主题名
_current_theme: str = "linear"


class Theme:
    """动态调色板 —— 所有属性均可在运行时通过 switch() 替换"""

    # ── 背景层级 ──────────────────────────────────────────
    BG_BASE      = "#0f0f13"
    BG_SURFACE   = "#16161e"
    BG_ELEVATED  = "#1c1c28"
    BG_HOVER     = "#1e1e2c"

    # 别名，保持向后兼容
    BG_PAGE = BG_BASE
    BG_CARD = BG_ELEVATED
    BG_INPUT = "#141418"

    # ── 文字层级 ──────────────────────────────────────────
    TEXT_PRIMARY   = "#e2e2ed"
    TEXT_SECONDARY = "#888899"
    TEXT_TERTIARY  = "#444455"
    TEXT_ON_ACCENT = "#ffffff"

    # 别名
    TEXT_MUTED = TEXT_TERTIARY
    TEXT_HINT = "#33334a"

    # ── 边框 ──────────────────────────────────────────────
    BORDER_LIGHT  = "#1e1e26"
    BORDER_MEDIUM = "#252530"
    BORDER_FOCUS  = "#7c6af5"

    # 别名
    BORDER_DEFAULT = BORDER_MEDIUM
    BORDER_SUBTLE = BORDER_LIGHT

    # ── 强调色 ────────────────────────────────────────────
    ACCENT_PRIMARY  = "#7c6af5"
    ACCENT_HOVER    = "#9080f8"
    ACCENT_PRESSED  = "#6858e0"
    ACCENT_LIGHT    = "#1c1a38"
    ACCENT_TEXT     = "#a89ff8"

    # 别名
    ACCENT_GOLD      = ACCENT_PRIMARY
    ACCENT_GOLD_BG   = ACCENT_LIGHT
    ACCENT_GOLD_TEXT = ACCENT_TEXT

    # ── 主操作色 ──────────────────────────────────────────
    ACTION_PRIMARY      = "#7c6af5"
    ACTION_PRIMARY_TEXT = "#ffffff"
    ACTION_HOVER        = "#9080f8"

    # ── 语义色 ────────────────────────────────────────────
    SUCCESS_BG   = "#0d2418"
    SUCCESS_TEXT = "#3ab56a"
    WARNING_BG   = "#2a2208"
    WARNING_TEXT = "#e8a838"
    ERROR_BG     = "#2a0e0e"
    ERROR_TEXT   = "#e85555"
    INFO_BG      = "#0d1a38"
    INFO_TEXT    = "#7c9af5"

    # 别名
    DANGER = ERROR_TEXT

    # ── 侧边栏专用 ────────────────────────────────────────
    SIDEBAR_BG          = "#09090d"
    SIDEBAR_ITEM_HOVER  = "#16161e"
    SIDEBAR_ITEM_ACTIVE = "#1c1a38"
    SIDEBAR_ACTIVE_TEXT = "#e2e2ed"

    # ── 标题栏 ────────────────────────────────────────────
    TITLEBAR_BG = "#09090d"

    @classmethod
    def switch(cls, name: str) -> None:
        """将所有类属性替换为指定预设的值，同步更新别名。"""
        # 兼容旧主题名
        name = _LEGACY_MAP.get(name, name)
        preset = _PRESETS.get(name)
        if preset is None:
            return
        for key, val in preset.items():
            setattr(cls, key, val)
        # 同步别名
        cls.BG_PAGE        = cls.BG_BASE
        cls.BG_CARD        = cls.BG_ELEVATED
        cls.TEXT_MUTED     = cls.TEXT_TERTIARY
        cls.BORDER_DEFAULT = cls.BORDER_MEDIUM
        cls.BORDER_SUBTLE  = cls.BORDER_LIGHT
        cls.ACCENT_GOLD      = cls.ACCENT_PRIMARY
        cls.ACCENT_GOLD_BG   = cls.ACCENT_LIGHT
        cls.ACCENT_GOLD_TEXT = cls.ACCENT_TEXT
        cls.DANGER           = cls.ERROR_TEXT


class Typography:
    """字体规范"""

    FONT_FAMILY = "Inter, -apple-system, Segoe UI, PingFang SC, Microsoft YaHei, sans-serif"

    SIZE_XS   = 11
    SIZE_SM   = 12
    SIZE_BASE = 13
    SIZE_MD   = 14
    SIZE_LG   = 16
    SIZE_XL   = 20

    WEIGHT_REGULAR = QFont.Normal
    WEIGHT_MEDIUM  = QFont.Medium
    WEIGHT_BOLD    = QFont.Bold


class Spacing:
    """间距规范"""

    XS  = 4
    SM  = 8
    MD  = 12
    LG  = 16
    XL  = 24
    XXL = 32

    CARD_PADDING      = 18
    SECTION_GAP       = 14
    BORDER_RADIUS_SM  = 6
    BORDER_RADIUS_MD  = 8
    BORDER_RADIUS_LG  = 10


# ──────────────────────────────────────────────────────────────
# 全局 QSS 生成函数（每次切换主题后重新调用）
# ──────────────────────────────────────────────────────────────

def build_qss() -> str:
    """根据当前 Theme 类属性生成全局 QSS 字符串。"""
    T = Theme
    S = Spacing
    Ty = Typography
    return f"""
/* ── 基础 ────────────────────────────────────────────── */
QWidget {{
    background-color: {T.BG_BASE};
    color: {T.TEXT_PRIMARY};
    font-family: {Ty.FONT_FAMILY};
    font-size: {Ty.SIZE_BASE}px;
}}

QMainWindow, QDialog {{
    background-color: {T.BG_BASE};
}}

QToolTip {{
    background-color: {T.BG_ELEVATED};
    color: {T.TEXT_PRIMARY};
    border: 1px solid {T.BORDER_MEDIUM};
    padding: 6px 10px;
    border-radius: {S.BORDER_RADIUS_SM}px;
}}

/* ── 按钮（默认 / Secondary）────────────────────────── */
QPushButton {{
    background-color: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 {T.BG_ELEVATED}, stop:1 {T.BG_SURFACE});
    color: {T.TEXT_PRIMARY};
    border: 1px solid {T.BORDER_LIGHT};
    border-radius: {S.BORDER_RADIUS_MD}px;
    padding: 7px 14px;
    font-size: {Ty.SIZE_BASE}px;
    font-weight: {Ty.WEIGHT_MEDIUM};
    min-height: 20px;
