# 向后兼容：模块级 GLOBAL_QSS（初始值，切换后通过 switch_theme 更新 app 样式）
GLOBAL_QSS = build_qss()


# ──────────────────────────────────────────────────────────────
# 公共接口
# ──────────────────────────────────────────────────────────────

def get_current_theme() -> str:
    """返回当前主题名称（"linear" | "light" | "rose" | "ember"）"""
    return _current_theme


def switch_theme(app, name: str) -> None:
    """
    切换主题并立即刷新 app 全局样式表。
    - 切换 Theme 类属性
    - 重新生成并应用 QSS
    - 更新 QPalette
    - 保存到 config
    """
    global _current_theme, GLOBAL_QSS
    # 兼容旧主题名
    name = _LEGACY_MAP.get(name, name)
    if name not in _PRESETS:
        return
    _current_theme = name
    Theme.switch(name)
    GLOBAL_QSS = build_qss()
    app.setStyleSheet(GLOBAL_QSS)
    _update_palette(app)
    _save_theme(name)


def _update_palette(app) -> None:
    """根据当前 Theme 更新 QPalette（影响 OS 级原生控件渲染）。"""
    from PyQt5.QtGui import QColor, QPalette
    palette = QPalette()
    palette.setColor(QPalette.Window,          QColor(Theme.BG_BASE))
    palette.setColor(QPalette.WindowText,      QColor(Theme.TEXT_PRIMARY))
    palette.setColor(QPalette.Base,            QColor(Theme.BG_INPUT))
    palette.setColor(QPalette.AlternateBase,   QColor(Theme.BG_SURFACE))
    palette.setColor(QPalette.ToolTipBase,     QColor(Theme.BG_ELEVATED))
    palette.setColor(QPalette.ToolTipText,     QColor(Theme.TEXT_PRIMARY))
    palette.setColor(QPalette.Text,            QColor(Theme.TEXT_PRIMARY))
    palette.setColor(QPalette.Button,          QColor(Theme.BG_ELEVATED))
    palette.setColor(QPalette.ButtonText,      QColor(Theme.TEXT_PRIMARY))
    palette.setColor(QPalette.BrightText,      QColor(Theme.ERROR_TEXT))
    palette.setColor(QPalette.Link,            QColor(Theme.ACCENT_PRIMARY))
    palette.setColor(QPalette.Highlight,       QColor(Theme.ACCENT_PRIMARY))
    palette.setColor(QPalette.HighlightedText, QColor(Theme.TEXT_ON_ACCENT))
    palette.setColor(QPalette.PlaceholderText, QColor(Theme.TEXT_HINT))
    palette.setColor(QPalette.Disabled, QPalette.Text,       QColor(Theme.TEXT_TERTIARY))
    palette.setColor(QPalette.Disabled, QPalette.ButtonText, QColor(Theme.TEXT_TERTIARY))
    palette.setColor(QPalette.Disabled, QPalette.WindowText, QColor(Theme.TEXT_TERTIARY))
    app.setPalette(palette)


def _save_theme(name: str) -> None:
    """持久化主题选择到 config（失败时静默忽略）。"""
    try:
        from core.config import config
        config.set("theme", name)
    except Exception:
        pass


def load_saved_theme(app) -> None:
    """启动时读取上次保存的主题并应用（若无记录则保持默认 linear）。"""
    try:
        from core.config import config
        name = config.get("theme", "linear")
        # 兼容旧主题名
        name = _LEGACY_MAP.get(name, name)
        if name != "linear":
            switch_theme(app, name)
    except Exception:
        pass


