def render_svg(svg_content: str, size: QSize, color: str = None) -> QPixmap:
    """将 SVG 字符串转换为指定大小和着色的 QPixmap"""
    from PyQt5.QtSvg import QSvgRenderer
    from PyQt5.QtGui import QPixmap, QPainter
    from PyQt5.QtCore import QByteArray, Qt

    if color:
        svg_content = svg_content.replace('currentColor', color)
        svg_content = svg_content.replace('fill="currentColor"', f'fill="{color}"')

    renderer = QSvgRenderer(QByteArray(svg_content.encode('utf-8')))
    pixmap = QPixmap(size)
    pixmap.fill(Qt.transparent)

    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()

    return pixmap

    def run(self):
        import random
        try:
            composer = VideoComposer()
            output_paths = []
            success_count = 0
            failed_count = 0

            for i in range(self.count):
                if self._should_stop:
                    break

                # 暂停检测：阻塞直到 resume() 被调用
                self._pause_event.wait()
                if self._should_stop:
                    break

                video_filename = f"output_{i+1:03d}.mp4"
                self.progress.emit(f"正在生成第 {i+1} / {self.count} 个视频...", i+1, self.count)
                self.step_progress.emit(f"处理分段 1/{len(self.segments)}…")

                try:
                    # 随机选择一个BGM文件
                    bgm_path = None
                    if self.bgm_files:
                        bgm_path = random.choice(self.bgm_files)

                    output_path = composer.compose(
                        self.segments,
                        timestamps=self.timestamps,
                        resolution=self.resolution,
                        fps=self.fps,
                        bgm_path=bgm_path,
                        bgm_volume=self.bgm_volume,
                        output_dir=self.output_dir,
                        index=i+1
                    )
                    output_paths.append(output_path)
                    success_count += 1
                    self.progress_detail.emit(i+1, self.count, video_filename, "success")
                except Exception as e:
                    failed_count += 1
                    self.progress_detail.emit(i+1, self.count, video_filename, "failed")

            self.finished.emit(output_paths)
        except Exception as e:
            self.error.emit(str(e))


class AudioDropFrame(QFrame):
    """支持拖拽音频文件的Frame"""
    files_dropped = pyqtSignal(list)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            event.ignore()

    def dropEvent(self, event):
        if event.mimeData().hasUrls():
            file_paths = []
            for url in event.mimeData().urls():
                if url.isLocalFile():
                    file_paths.append(url.toLocalFile())
            if file_paths:
                self.files_dropped.emit(file_paths)
            event.acceptProposedAction()
        else:
            event.ignore()

    )
    if paths:
        self._load_txt_files(sorted(paths))

def _on_files_dropped(self, paths: list):
    """处理拖拽进入的文件列表（.txt 和 .json 混合均可）。"""
    txt_files  = [p for p in paths if p.lower().endswith('.txt')]
    json_files = [p for p in paths if p.lower().endswith('.json')]

    if txt_files:
        self._load_txt_files(txt_files)
    for p in json_files:
        self._load_json_file(p)

def _load_txt_files(self, paths: list):
    """逐个读取 .txt 文件并加入队列（按传入顺序）。"""
    loaded = 0
    for p in paths:
        try:
            text = Path(p).read_text(encoding='utf-8').strip()
            if not text:
                self._log(f'⚠️ 跳过空文件：{Path(p).name}')
                continue
            self._add_script(text)
            loaded += 1
        except Exception as e:
            self._log(f'⚠️ 读取失败 {Path(p).name}：{e}')
    if loaded:
        self._log(f'已导入 {loaded} 个 TXT 文件')

def _load_json_file(self, path: str):
    """读取单个 JSON 文件并批量加入队列。"""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if not isinstance(data, list):
            QMessageBox.warning(self, '格式错误', f'{Path(path).name}\nJSON 文件应为列表格式：["文案1", "文案2", ...]')
            return
        texts = [str(x).strip() for x in data if str(x).strip()]
        for t in texts:
            self._add_script(t)
        self._log(f'已导入 {len(texts)} 条脚本（{Path(path).name}）')
    except Exception as e:
        QMessageBox.critical(self, '读取失败', f'无法读取 JSON 文件：\n{e}')

def _on_import_json(self):
    default_dir = os.path.expanduser('~')
    path, _ = QFileDialog.getOpenFileName(
        self, '导入脚本 JSON', default_dir,
        'JSON 文件 (*.json);;所有文件 (*.*)'
    )
    if not path:
        return
    self._load_json_file(path)

def _on_add_manual(self):
    dlg = _InputDialog(self)
    if dlg.exec_():
        text = dlg.get_text()
        if text:
            self._add_script(text)

def _on_delete_selected(self):
    rows = sorted(set(i.row() for i in self.queue_list.selectedIndexes()), reverse=True)
    for row in rows:
        self.queue_list.takeItem(row)
        self._queue.pop(row)
        self._item_widgets.pop(row)
    # 重新编号
    for i, w in enumerate(self._item_widgets):
        w.idx_label.setText(f"{i + 1:02d}")
    self._update_count()

def _on_clear_queue(self):
    if self._running:
        QMessageBox.warning(self, '执行中', '请先终止执行再清空队列')
        return
    self.queue_list.clear()
    self._queue.clear()
    self._item_widgets.clear()
    self._update_count()

@staticmethod
def _clean_script(text: str) -> str:
    """剥离 LLM 偶尔返回的 JSON 包裹，如 {"rewritten": "..."} 或 ```json...```"""
    import re, json as _json
    t = text.strip()
    # 去掉 markdown 代码块
    t = re.sub(r'^```(?:json)?\s*', '', t, flags=re.IGNORECASE)
    t = re.sub(r'\s*```$', '', t).strip()
    # 尝试解析 JSON，取常见字段
    if t.startswith('{'):
        try:
            obj = _json.loads(t)
            for key in ('rewritten', 'content', 'text', 'result', 'output'):
                if key in obj and isinstance(obj[key], str):
                    return obj[key].strip()
        except Exception:
            pass
    return t

def _add_script(self, text: str):
    text = self._clean_script(text)
    if not text:
        return
    item_data = ScriptItem(text)
    self._queue.append(item_data)

    idx = len(self._queue) - 1
    widget = ScriptItemWidget(idx, text)
    self._item_widgets.append(widget)

    from PyQt5.QtCore import QSize
    list_item = QListWidgetItem()
    # 文案超过40字时显示两行，给足高度
    height = 68 if len(text.replace('\n', ' ').strip()) > 40 else 48
    list_item.setSizeHint(QSize(0, height))
    self.queue_list.addItem(list_item)
    self.queue_list.setItemWidget(list_item, widget)

    self._update_count()

def add_scripts_from_library(self, scripts: list[str]):
    """Public entry point used by the benchmark script library page."""
    added = 0
    for text in scripts:
        before = len(self._queue)
        self._add_script(text)
        if len(self._queue) > before:
            added += 1
    if added:
        self._log(f'已从文案库导入 {added} 条脚本')
    return added

def _update_count(self):
    self.queue_count_label.setText(f"共 {len(self._queue)} 条脚本")

