def _on_seg_mode_changed(self, _):
    mode = self.seg_mode_combo.currentData()
    self.seg_text_widget.setVisible(mode == 'text')
    self.seg_dur_widget.setVisible(mode == 'duration')
    self.seg_count_widget.setVisible(mode == 'count')

